       while (true) {
         this.refill();
         if (this.tokens >= 1) {
           this.tokens -= 1;
           return;
         }
         const waitMs = ((1 - this.tokens) / this.refillRate) * 1000;
         await new Promise(res => setTimeout(res, waitMs));
       }
     }
   }

